WITH enriched AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, NTILE(10) OVER (PARTITION BY plan ORDER BY monthly_fee, id) AS monthly_fee_bucket, DENSE_RANK() OVER w_part AS monthly_fee_dense_rank, LAST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY plan ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee FROM subscriptions WINDOW w_part AS (PARTITION BY customer_id ORDER BY monthly_fee DESC NULLS LAST)) SELECT DATE_TRUNC('MONTH', start_date) AS activity_month, DATE_TRUNC('YEAR', end_date) AS year_start, PERCENTILE_APPROX(monthly_fee_bucket, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_bucket_quartiles, SUM(monthly_fee_bucket) FILTER (WHERE status = 'PAUSED') AS paused_total_monthly_fee_bucket, GROUPING(DATE_TRUNC('MONTH', start_date)) AS gid FROM enriched GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', start_date), DATE_TRUNC('YEAR', end_date)), (DATE_TRUNC('MONTH', start_date))) HAVING paused_total_monthly_fee_bucket >= 0 ORDER BY activity_month DESC;
